def get_max(nums):
    if not nums:
        return None
    else:
        max_num = nums[0]
        for num in nums:
            if num > max_num:
                max_num = num
        return max_num

def fact(n):
    if n == 1: 
        return 1
    return n * fact(n-1)

def is_palindrome(s):
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s == s[::-1]

def fizzbuzz(n):
    if n % 3 == 0 and n % 5 == 0:
        return "FizzBuzz"
    elif n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    else:
        return str(n)

def count_vowels(s):
    s = s.lower()
    return sum(1 for char in s if char in 'aeiou')

def nth_fib(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

def are_anagrams(a, b):
    # Convert both strings to lowercase and sort their characters
    return sorted(a.lower()) == sorted(b.lower())
